    $('[id*=cmdConsulta_Itens]').click(async function (e) {
        e.preventDefault();
        $('[id*=div_Loading]').show();
        $('[id*=div_img]').show();

        bConsulta_Itens = true;

        const botao = $(this);
        let gruposSelecionados = $("[id*=lstFiltros_Consulta] option:selected").map(function () { return $(this).val(); }).get().join("|");
        if (botao.hasClass('todos') || gruposSelecionados.includes('-1|')) {
            gruposSelecionados = '-1';
        }

        await $.ajax({
            url: "/App/Paginas/Comercial/Tabelas_Detalhe.aspx/GetItens_Tabela",
            data: JSON.stringify({ idTabela: idTabela, bNacional: bNacional, sGrupos: gruposSelecionados }),
            type: 'POST',
            dataType: 'json',
            contentType: 'application/json; charset=utf-8',
            success: function (response) {
                list_ItensTabela = JSON.parse(response.d);

                ManipulaCampos_x_Permissao();

                list_ItensTabela.forEach(item => {
                    item.NTotal = calculaTotal_Item(item);
                });

                dtgItens_DataBind();

                if (bExibe_ControleValores) {
                    window.gvControleValores_DataBind(list_ItensTabela);
                }
            },
            error: function (error) {
                ExibirMensagem_Validacao(3, 3, "<b>Erro: </b>Houve um erro na Consulta dos Itens da Tabela!<br />Erro ao Consultar Itens: " + RetornaMensagem_Erro(error));
            }
        }).always(function () {
            bConsulta_Itens = false;
            setTimeout(function () {
                $('[id*=div_Loading]').hide();
                $('[id*=div_img]').hide();
            }, 50);
        });
    });

