    $('[id*=cmdIncluir_Item]').on('click', function (e) {
        e.preventDefault();
        $this = $(this);
        $this.attr('disabled', '');
        $('[id*=div_Loading]').show();
        $('[id*=div_img]').show();

        try {
            const id = parseInt($('[id*=hddComposicao_idItem]').val());
            const codigo = $('[id*=txtComposicao_sCodigoProduto]').val();
            const descricao = $('[id*=txtComposicao_sDscProduto]').val();
            const valor = $('[id*=txtPreco]').val() || 0;

            if (codigo.length <= 0) {
                ExibirMensagem_Validacao(2, 3, 'É necessário preencher o campo de Código!');
                $('[id*=txtComposicao_sCodigoProduto]').focus();
            } else if (descricao.length <= 0) {
                ExibirMensagem_Validacao(2, 3, 'É necessário preencher o campo de Descrição!');
                $('[id*=txtComposicao_sDscProduto]').focus();
            } else if (valor.length <= 0) {
                ExibirMensagem_Validacao(2, 3, 'É necessário preencher o campo de Valor!');
                $('[id*=txtPreco]').focus();
            } else if (id <= 0) {
                ExibirMensagem_Validacao(2, 3, 'Item não encontrado para Inclusão!');
            } else {
                let itemExistente = list_ItensTabela.find(item => item.IdItem === id);
                const idGrupoProduto = parseInt($('[id*=hddComposicao_idGrupo]').val() || 0);
                if (list_ItensTabela.length && !itemExistente) {
                    const nII = parseFloat(String($('[id*=hddComposicao_nII]').val()).replace('.', '').replace(',', '.')) || 0;
                    const nIPI = parseFloat(String($('[id*=hddComposicao_nIPI]').val()).replace('.', '').replace(',', '.')) || 0;
                    const nPIS = parseFloat(String($('[id*=hddComposicao_nPIS]').val()).replace('.', '').replace(',', '.')) || 0;
                    const nCOFINS = parseFloat(String($('[id*=hddComposicao_nCOFINS]').val()).replace('.', '').replace(',', '.')) || 0;
                    const nICMS = parseFloat(String($('[id*=hddComposicao_nICMS]').val()).replace('.', '').replace(',', '.')) || 0;
                    let novoItem = {
                        nOrdem: list_ItensTabela[list_ItensTabela.length - 1].nOrdem + 10, IdItem: id, IdTabelaOrigem: 0, SDscProduto: descricao, SCodigo: codigo, SCodigoComDescricao: codigo + ' - ' + descricao,
                        TipoProduto: $('[id*=hddComposicao_sDscTipoProduto]').val(), IdGrupoProduto: idGrupoProduto, IdFamiliaProduto: parseInt($('[id*=hddComposicao_idFamilia]').val() || 0),
                        sDscGrupoProduto: $('[id*=hddComposicao_sDscGrupo]').val(), sDscFamiliaProduto: $('[id*=hddComposicao_sDscFamilia]').val(), Preco: parseFloat(String(valor).replace('.', '').replace(',', '.')),
                        Preco_Zona_SD: 0, Preco_Zona_ND: 0, Preco_Zona_N: 0, Preco_Zona_CO: 0, Preco_Zona_S: 0, NFator: parseFloat(String((idTipoTabela == 1 || idTipoTabela == 11 ? $('.descontoGlobal').val() || 0 : $('.fatorGlobal').val() || '0')).replace('.', '').replace(',', '.')),
                        NMargem: parseFloat(String(($('.margemGlobal').val() || '0')).replace('.', '').replace(',', '.')), NEnvio: parseFloat(String(($('.txEnvioGlobal').val() || '0')).replace('.', '').replace(',', '.')),
                        NLocal: parseFloat(String(($('.txLocalGlobal').val() || '0')).replace('.', '').replace(',', '.')), NII: nII, NIPI: nIPI, NPIS: nPIS, NCOFINS: nCOFINS, NICMS: nICMS,
                        nVlr_II: 0, nVlr_IPI: 0, nVlr_PIS: 0, nVlr_COFINS: 0, nVlr_ICMS: 0, NImpostos: 0, NTotal: 0, SUnidade: $('[id*=hddComposicao_sUnidade]').val(), DtAtualizacao: 'Não cadastrado', dtInclusao: 'Não cadastrado',
                        SFuncao: 'INCLUIR_ITEM', bLiberado: false, bImportado: false, sIndustrializado: $('[id*=hddComposicao_sIndustrializado]').val()
                    };
                    novoItem.NTotal = calculaTotal_Item(novoItem);
                    list_ItensTabela.push(novoItem);
                    ExibirMensagem_Validacao(2, 2, 'Item Incluído com sucesso!');
                } else if (itemExistente) {
                    if (itemExistente.SFuncao === 'EXCLUIR_ITEM') {
                        itemExistente.SFuncao = 'INCLUIR_ITEM';
                        itemExistente.Preco = parseFloat(String(valor).replace('.', '').replace(',', '.'));
                        itemExistente.NTotal = calculaTotal_Item(itemExistente);
                        ExibirMensagem_Validacao(2, 2, 'Item Incluído com sucesso!');
                    } else {
                        ExibirMensagem_Validacao(2, 3, 'Item já cadastrado na Tabela de Preços!');
                    }
                } else {
                    const nII = parseFloat(String($('[id*=hddComposicao_nII]').val()).replace('.', '').replace(',', '.')) || 0;
                    const nIPI = parseFloat(String($('[id*=hddComposicao_nIPI]').val()).replace('.', '').replace(',', '.')) || 0;
                    const nPIS = parseFloat(String($('[id*=hddComposicao_nPIS]').val()).replace('.', '').replace(',', '.')) || 0;
                    const nCOFINS = parseFloat(String($('[id*=hddComposicao_nCOFINS]').val()).replace('.', '').replace(',', '.')) || 0;
                    const nICMS = parseFloat(String($('[id*=hddComposicao_nICMS]').val()).replace('.', '').replace(',', '.')) || 0;
                    let novoItem = {
                        nOrdem: 0, IdItem: id, IdTabelaOrigem: 0, SDscProduto: descricao, SCodigo: codigo, SCodigoComDescricao: codigo + ' - ' + descricao,
                        TipoProduto: $('[id*=hddComposicao_sDscTipoProduto]').val(), IdGrupoProduto: idGrupoProduto, IdFamiliaProduto: parseInt($('[id*=hddComposicao_idFamilia]').val() || 0),
                        sDscGrupoProduto: $('[id*=hddComposicao_sDscGrupo]').val(), sDscFamiliaProduto: $('[id*=hddComposicao_sDscFamilia]').val(), Preco: parseFloat(String(valor).replace('.', '').replace(',', '.')),
                        Preco_Zona_SD: 0, Preco_Zona_ND: 0, Preco_Zona_N: 0, Preco_Zona_CO: 0, Preco_Zona_S: 0, NFator: parseFloat(String((idTipoTabela == 1 || idTipoTabela == 11 ? $('.descontoGlobal').val() || 0 : $('.fatorGlobal').val() || '0')).replace('.', '').replace(',', '.')),
                        NMargem: parseFloat(String(($('.margemGlobal').val() || '0')).replace('.', '').replace(',', '.')), NEnvio: parseFloat(String(($('.txEnvioGlobal').val() || '0')).replace('.', '').replace(',', '.')),
                        NLocal: parseFloat(String(($('.txLocalGlobal').val() || '0')).replace('.', '').replace(',', '.')), NII: nII, NIPI: nIPI, NPIS: nPIS, NCOFINS: nCOFINS, NICMS: nICMS,
                        nVlr_II: 0, nVlr_IPI: 0, nVlr_PIS: 0, nVlr_COFINS: 0, nVlr_ICMS: 0, NImpostos: 0, NTotal: 0, SUnidade: $('[id*=hddComposicao_sUnidade]').val(), DtAtualizacao: 'Não cadastrado', dtInclusao: 'Não cadastrado',
                        SFuncao: 'INCLUIR_ITEM', bLiberado: false, bImportado: false, sIndustrializado: $('[id*=hddComposicao_sIndustrializado]').val()
                    };
                    novoItem.NTotal = calculaTotal_Item(novoItem);
                    list_ItensTabela.push(novoItem);
                    ExibirMensagem_Validacao(2, 2, 'Item Incluído com sucesso!');
                }

                if (idTabela) Popula_Filtro_Grupos();

                $('[id*=txtComposicao_sCodigoProduto]').val('').focus();
                $('[id*=txtComposicao_sDscProduto]').val('');
                $('[id*=txtPreco]').val('');
            }
        } catch (erro) {
            ExibirMensagem_Validacao(2, 3, '<b>Erro: </b>Houve um erro na tentativa de adicionar o Novo Item! < br /> Erro ao Incluir:' + erro.message);
        }

        ManipulaCampos_x_Permissao();
        dtgItens_DataBind();
        setTimeout(function () {
            $this.removeAttr('disabled');
            $('[id*=div_Loading]').hide();
            $('[id*=div_img]').hide();
        }, 50);
    });

    $('.vincularTabelas').on('click', async function (e) {
        e.preventDefault();
        $this = $(this);
        $this.attr('disabled', '');
        $('[id*=div_Loading]').show();
        $('[id*=div_img]').show();

        let sIDs_Tabelas = $('[id*=lstTabelas]').val();

        if (sIDs_Tabelas.length) {
            await $.ajax({
                url: "/App/Paginas/Comercial/Tabelas_Detalhe.aspx/Get_ImportarProdutos",
                data: JSON.stringify({ tabelas: sIDs_Tabelas, idMoedaOrigem: idMoedaOrigem }),
                type: 'POST',
                dataType: 'json',
                contentType: 'application/json; charset=utf-8',
                success: function (response) {
                    importarItens(response.d, true);

                    hddIdsTabelasImportadas.val(hddIdsTabelasImportadas.val() + sIDs_Tabelas.join('|'))

                    ManipulaCampos_x_Permissao();
                    dtgItens_DataBind();
                },
                error: function (error) {
                    ExibirMensagem_Validacao(1, 3, "<b>Erro: </b>Houve um erro na Consulta dos Itens para Vincular Tabelas!<br />Erro ao Vincular Tabelas: " + RetornaMensagem_Erro(error));
                }
            }).always(function () {
                setTimeout(function () {
                    $this.removeAttr('disabled');
                    $('[id*=div_Loading]').hide();
                    $('[id*=div_img]').hide();
                }, 50);
            });
        } else {
            ExibirMensagem_Validacao(1, 3, '<b>Erro: </b>É necessário selecionar ao menos uma Tabela para ser Vinculada!');
            $('[id*=lstTabelas]').focus();
            setTimeout(function () {
                $this.removeAttr('disabled');
                $('[id*=div_Loading]').hide();
                $('[id*=div_img]').hide();
            }, 50);
        }
    });

