    $('[id*=cmdImportarItens_Excel_Modal]').on('click', function (e) {
        e.preventDefault();
        $this = $(this);
        $this.attr('disabled', '');
        $('[id*=div_Loading]').show();
        $('[id*=div_img]').show();

        let arquivo = $('[id*=ImportarArquivo]')[0].files[0];

        if (!arquivo) {
            ExibirMensagem_Validacao(8, 3, '<b>Erro: </b>É necessário selecionar um Arquivo para Importar!');
        } else {
            let reader = new FileReader();

            reader.onload = function (e) {
                let data = new Uint8Array(e.target.result);
                let workbook = XLSX.read(data, { type: "array" });

                let worksheet = workbook.Sheets[workbook.SheetNames[0]];

                let json = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

                let itens = json.map(row => ({
                    SCodigo: String(row[0] || ""),
                    Preco: parseFloat(row[1]) || 0
                }));

                $.ajax({
                    url: "/App/Paginas/Comercial/Tabelas_Detalhe.aspx/Get_ImportarProdutos_x_Excel",
                    data: JSON.stringify({ itens: itens, idTipoTabela: idTipoTabela }),
                    type: 'POST',
                    dataType: 'json',
                    contentType: 'application/json; charset=utf-8',
                    success: function (response) {
                        importarItens(response.d, false);

                        ExibirMensagem_Validacao(8, 2, 'Todos os Produtos foram Importados com sucesso!');

                        ManipulaCampos_x_Permissao();
                        dtgItens_DataBind();
                    },
                    error: function (error) {
                        ExibirMensagem_Validacao(8, 3, "<b>Erro: </b>Houve um erro na Consulta dos Itens para Importação!<br />Erro ao Importar Itens por Arquivo Excel: " + RetornaMensagem_Erro(error));
                    }
                }).always(function () {
                    setTimeout(function () {
                        $this.removeAttr('disabled');
                        $('[id*=div_Loading]').hide();
                        $('[id*=div_img]').hide();
                    }, 50);
                });
            };

            reader.readAsArrayBuffer(arquivo);
        }

        setTimeout(function () {
            $this.removeAttr('disabled');
            $('[id*=div_Loading]').hide();
            $('[id*=div_img]').hide();
        }, 50);
    });

